import Testing
@testable import GammaEngage

/// Expected values were generated by Node (JSON.stringify + crypto) — the server's own primitives.
struct EventSignerTests {

    @Test func plainBodyAndSignatureMatchNode() {
        let body = EventSigner.buildBody(
            eventType: "push_token_registered",
            brandId: "brand-1",
            playerId: "player-123",
            payload: [("device_token", "tok:en-_1"), ("platform", "ios")],
            eventId: "evt-1",
            idempotencyKey: "idem-1",
            occurredAt: "2026-09-30T07:00:00.000Z"
        )
        #expect(body == "{\"schema_version\":\"1.0\",\"event_id\":\"evt-1\",\"event_type\":\"push_token_registered\",\"brand_id\":\"brand-1\",\"source_system\":\"ios-sdk\",\"occurred_at\":\"2026-09-30T07:00:00.000Z\",\"player_ref\":{\"external_player_id\":\"player-123\"},\"payload\":{\"device_token\":\"tok:en-_1\",\"platform\":\"ios\"},\"idempotency_key\":\"idem-1\"}")
        #expect(EventSigner.hmacHex(secret: "s3cret", body: body) == "88bff68b1b5c873c61ecf536c401cca5a129163dbe166f31faefed058e9e0372")
    }

    @Test func trickyBodyAndSignatureMatchNode() {
        let body = EventSigner.buildBody(
            eventType: "push_token_registered",
            brandId: "brand-1",
            playerId: "pl/ay\"er\\1\u{a}\u{1}\u{e9}\u{1f600} tab\u{9}here",
            payload: [("device_token", "tok:en-_1"), ("platform", "ios")],
            eventId: "evt-1",
            idempotencyKey: "idem-1",
            occurredAt: "2026-09-30T07:00:00.000Z"
        )
        #expect(body == "{\"schema_version\":\"1.0\",\"event_id\":\"evt-1\",\"event_type\":\"push_token_registered\",\"brand_id\":\"brand-1\",\"source_system\":\"ios-sdk\",\"occurred_at\":\"2026-09-30T07:00:00.000Z\",\"player_ref\":{\"external_player_id\":\"pl/ay\\\"er\\\\1\\n\\u0001\u{e9}\u{1f600} tab\\there\"},\"payload\":{\"device_token\":\"tok:en-_1\",\"platform\":\"ios\"},\"idempotency_key\":\"idem-1\"}")
        #expect(EventSigner.hmacHex(secret: "s3cret", body: body) == "02377e8b6b5027dad531148f5b7723bd360089533b64e3212680acc8a9eca6ca")
    }
}
